package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Civics (පුරවැසි අධ්‍යාපනය).
 * Part 2: Categories 11 to 20 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankCivicsSetsPart2 {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      11 -> if (grade == "11") set11_Grade11[(c - 1) % set11_Grade11.size] else set11_Grade10[(c - 1) % set11_Grade10.size]
      12 -> if (grade == "11") set12_Grade11[(c - 1) % set12_Grade11.size] else set12_Grade10[(c - 1) % set12_Grade10.size]
      13 -> if (grade == "11") set13_Grade11[(c - 1) % set13_Grade11.size] else set13_Grade10[(c - 1) % set13_Grade10.size]
      14 -> if (grade == "11") set14_Grade11[(c - 1) % set14_Grade11.size] else set14_Grade10[(c - 1) % set14_Grade10.size]
      15 -> if (grade == "11") set15_Grade11[(c - 1) % set15_Grade11.size] else set15_Grade10[(c - 1) % set15_Grade10.size]
      16 -> if (grade == "11") set16_Grade11[(c - 1) % set16_Grade11.size] else set16_Grade10[(c - 1) % set16_Grade10.size]
      17 -> if (grade == "11") set17_Grade11[(c - 1) % set17_Grade11.size] else set17_Grade10[(c - 1) % set17_Grade10.size]
      18 -> if (grade == "11") set18_Grade11[(c - 1) % set18_Grade11.size] else set18_Grade10[(c - 1) % set18_Grade10.size]
      19 -> if (grade == "11") set19_Grade11[(c - 1) % set19_Grade11.size] else set19_Grade10[(c - 1) % set19_Grade10.size]
      20 -> if (grade == "11") set20_Grade11[(c - 1) % set20_Grade11.size] else set20_Grade10[(c - 1) % set20_Grade10.size]
      else -> if (grade == "11") set11_Grade11[(c - 1) % set11_Grade11.size] else set11_Grade10[(c - 1) % set11_Grade10.size]
    }
  }

  // --- SET 11: ඡන්ද බලය, මැතිවරණ & මහජන නියෝජනය ---

  // --- SET 12: මහජන මතය, ජනමාධ්‍ය & තොරතුරු දැනගැනීමේ අයිතිය ---
